DARK_STYLE = '''QWidget { background: #0d1224; color: #e8ecff; font-family: Segoe UI; font-size: 14px; } QLabel#title { color: #8ea7ff; font-size: 32px; font-weight: 700; } QPushButton { background: #4657d6; border: 0; border-radius: 8px; padding: 10px 18px; color: white; font-weight: 600; } QPushButton:hover { background: #6170ef; } QPushButton:disabled { background: #30364f; color: #8490b3; } QLineEdit, QTextEdit { background: #171e37; border: 1px solid #2c3760; border-radius: 8px; padding: 8px; } QGroupBox { border: 1px solid #27325b; border-radius: 10px; margin-top: 10px; padding: 12px; }'''
